import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

primes_to_check = [2, 3, 5, 7, 11, 13, 17, 19]
results = {}

for q in primes_to_check:
    # Calculate N = q^2 - q + 1
    N = q*q - q + 1

    # Check if N is a perfect cube
    # Calculate the integer cube root approximation
    k_approx = round(N**(1/3))

    # Check if k_approx cubed equals N
    if k_approx**3 == N:
        k = k_approx

        # Check the conditions: k is prime and k != q
        is_k_prime = is_prime(k)
        is_k_different_from_q = k != q

        results[q] = (N, k, is_k_prime, is_k_different_from_q)
    else:
        results[q] = (N, None, False, False)

# Format and print results
print("--- Checking primes q ---")
for q, data in results.items():
    N, k, is_k_prime, is_k_different_from_q = data
    if k is not None:
        print(f"q = {q}: N = {N} = {k}^3. k is prime? {is_k_prime}. k != q? {is_k_different_from_q}. SUCCESS: {is_k_prime and is_k_different_from_q}")
    else:
        print(f"q = {q}: N = {N}. Not a perfect cube.")
